// HasWorkstream applies the HasEdge predicate on the "workstream" edge.
func HasWorkstream() predicate.WorkProgramRun {
	return predicate.WorkProgramRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, WorkstreamTable, WorkstreamColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkstreamWith applies the HasEdge predicate on the "workstream" edge with a given conditions (other predicates).
func HasWorkstreamWith(preds ...predicate.Workstream) predicate.WorkProgramRun {
	return predicate.WorkProgramRun(func(s *sql.Selector) {
		step := newWorkstreamStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

