// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkProgramRun) predicate.WorkProgramRun {
	return predicate.WorkProgramRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkProgramRun) predicate.WorkProgramRun {
	return predicate.WorkProgramRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkProgramRun) predicate.WorkProgramRun {
	return predicate.WorkProgramRun(sql.NotPredicates(p))
}
